INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-18-s0-1', 'exam-linear-algebra-set-18', 'exam-linear-algebra-set-18-sec-0', 0, '是一组线性无关的n维列向量，则', '$\\alpha_{1},\\alpha_{2},\\cdots,\\alpha_{m}$ 是一组线性无关的 n 维列向量，则（）。', '["对任一组数 $k_{1},k_{2},\\\\cdots,k_{m},k_{1}\\\\alpha_{1}+k_{2}\\\\alpha_{2}+\\\\cdots+k_{m}\\\\alpha_{m}=0$ 都不成立","对任一组不全为零的数 $k_{1},k_{2},\\\\cdots,k_{m},k_{1}\\\\alpha_{1}+k_{2}\\\\alpha_{2}+\\\\cdots+k_{m}\\\\alpha_{m}=0$ 都不成立","其中可能存在一向量能由是其余向量的线性表示","其中任一向量都能可由其余向量线性表示"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第18套', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
